import {LEVELS,connections} from './architecture.js';
export function liftFloors(s){return LEVELS.filter(y=>{const i=LEVELS.indexOf(y);return connections(s.phase,s.experiment,s.doors).some(c=>c.status==='pass'&&(c.bodyA==='F'+i||c.bodyB==='F'+i));});}
export function beginLift(s){if(s.mode!=='idle'||s.liftActive)return false;const own=s.owner;if(own==='lift'){if(s.player.x>-3.15){s.message='かごの奥へ進んでからEを押してください。';return false;}s.liftPassenger=true;s.liftState='closing';s.liftActive=true;s.message='扉を閉じています。閉鎖後に行先を選択してください。';}else if(/^F\d+$/.test(own??'')){if(Math.abs(s.liftY-s.player.y)<.01){s.message='かごへ歩いて入り、内部でEを押してください。';return false;}s.liftPassenger=false;s.liftTarget=s.player.y;s.liftState='closing';s.liftActive=true;s.message='固定EVをこの乗場へ呼びます。';}else{s.message='固定EVの乗場か、かご内で操作してください。';return false;}s.invalidate();return true;}
export function chooseLift(s,y){if(s.liftState!=='selecting'||!s.liftPassenger||y===s.liftY||!liftFloors(s).includes(y))return false;s.liftTarget=y;s.liftFrom=s.liftY;s.liftTime=0;s.liftState='moving';s.message='扉の閉鎖を確認。選択した階へ昇降します。';return true;}
export function cancelLift(s){if(!s.liftPassenger||!['closing','selecting'].includes(s.liftState))return false;s.liftTarget=s.liftY;s.liftState='opening';s.message='行先選択を取り消しました。同じ階で扉を開きます。';return true;}
export function tickLift(s,dt){if(!s.liftActive)return;if(s.liftState==='closing'){s.liftGate=Math.min(1,s.liftGate+dt/.55);if(s.liftGate===1){if(s.liftPassenger){s.liftState='selecting';s.message='移動先を選択してください。';}else{s.liftFrom=s.liftY;s.liftTime=0;s.liftState='moving';}}}else if(s.liftState==='moving'){s.liftTime+=Math.min(.1,dt)*s.speed;const t=Math.min(1,s.liftTime/5);s.liftY=s.liftFrom+(s.liftTarget-s.liftFrom)*t;if(s.liftPassenger)s.player.y=s.liftY;if(t===1){s.liftState='opening';s.message='着床を確認。扉を開きます。';}}else if(s.liftState==='opening'){s.liftGate=Math.max(0,s.liftGate-dt/.55);if(s.liftGate===0){s.liftState='open';s.liftActive=false;s.message='固定EVが着床しました。通常の探索へ戻れます。';}}s.invalidate();}
